(6002, 6002, 'EMPRESA', 'Samsung Experience Store', 'Showroom oficial Samsung en Cartagena. Smartphones insignia Galaxy S24 Ultra, plegables Galaxy Z, tabletas Galaxy Tab S9 y televisores Neo QLED.', '/images/stores/logos/samsung-store.png', '/images/stores/banners/samsung-store.webp', '/images/stores/banners/samsung-store.webp', 'APROBADO', '860069284-9', 'Samsung Experience Store S.A.S.', 'Cartagena de Indias', 'C.C. Mallplaza El Castillo Local 118, El Cabrero, Cartagena de Indias', '104-582910-88', 'Davivienda', 4.9, 27, 'ELITE', NOW() - INTERVAL '26 days'),
